namespace Game_Catalog.Models
{
    /// <summary> Represents a video game development studio. </summary>
    public class Studio
    {
        /// <summary> Unique identifier of the studio. Generated by the database. </summary>
        public int StudioId { get; set; }

        private string _studioName = string.Empty;
        /// <summary> Name of the studio. </summary>
        public string StudioName
        {
            get => _studioName;
            set => _studioName = value ?? string.Empty;
        }

        private string _country = string.Empty;
        /// <summary> Country where the studio is based. Empty means unknown. </summary>
        public string Country
        {
            get => _country;
            set => _country = value ?? string.Empty;
        }

        /// <summary> The year the studio was founded. Null if unknown. </summary>
        public int? FoundationYear { get; set; }

        /// <summary> Identifier of the main genre. Null if not set. </summary>
        public int? MainGenre { get; set; }

        private string _mainGenreName = string.Empty;
        /// <summary> Name of the main genre, loaded together with the studio. </summary>
        public string MainGenreName
        {
            get => _mainGenreName;
            set => _mainGenreName = value ?? string.Empty;
        }

        private string _website = string.Empty;
        /// <summary> Official website of the studio. Empty means unknown. </summary>
        public string Website
        {
            get => _website;
            set => _website = value ?? string.Empty;
        }
    }
}